_MARKER_RE = re.compile(
    r"^\s*<!--\s+larch:clarify-(request|response)\s+id=([1-9][0-9]*)\s*-->\s*$"
)
_COMMENT_ID_RE = re.compile(r"issuecomment-([0-9]+)")
